import XCTest

class BookClubLongPressTest: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testLongPressBookClubRoom() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")

        // Find the Book Club room in the chat list
        // Looking for the cell with "Book Club" text and the message preview
        let bookClubPredicate = NSPredicate(format: "label CONTAINS[cd] 'Book Club'")
        let bookClubRoom = app.cells.containing(bookClubPredicate).firstMatch

        if !bookClubRoom.exists {
            // Try a different approach - look for the static text "Book Club"
            let bookClubText = app.staticTexts["Book Club"]
            let bookClubCell = bookClubText.firstMatch.coordinate(withNormalizedOffset: CGVector(dx: -0.4, dy: 0))

            // Perform a long press for 1 second
            bookClubCell.press(forDuration: 1.0)
        } else {
            // Perform a long press on the cell
            let cellCenter = bookClubRoom.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
            cellCenter.press(forDuration: 1.0)
        }

        // Verify context menu appears
        let contextMenu = app.menus.firstMatch
        XCTAssertTrue(contextMenu.waitForExistence(timeout: 2.0), "Context menu should appear")
    }
}

